INSERT INTO Product (ProductID, ProductName, CategoryID, AuthorID, PublisherID, SupplierID, Price, OriginalPrice, ImageUrl, Description, IsFeatured, IsFlashSale, IsActive, CreatedAt) VALUES
    (1, N'Nhà Giả Kim', 8, 1, 4, 1, 63200, 79000, N'/images/products/p001.jpg', N'Hành trình của cậu bé chăn cừu Santiago rời quê hương đi tìm kho báu ở chân Kim Tự Tháp Ai Cập. Trên đường đi, cậu học cách lắng nghe trái tim, đọc những dấu hiệu của cuộc sống và theo đuổi vận mệnh của riêng mình. Một câu chuyện ngụ ngôn giản dị nhưng truyền cảm hứng cho hàng triệu độc giả trên thế giới.', 1, 0, 1, '2025-12-27T16:19:00'),
    (2, N'Rừng Na Uy', 8, 2, 4, 1, 112500, 150000, N'/images/products/p002.jpg', N'Nghe lại bài hát Norwegian Wood, Toru Watanabe nhớ về những năm tháng sinh viên ở Tokyo cuối thập niên 60, về Naoko mong manh và Midori đầy sức sống. Cuốn tiểu thuyết là bức chân dung đầy hoài niệm về tình yêu, sự mất mát và tuổi trẻ cô đơn.', 0, 1, 1, '2025-11-07T13:25:00'),
    (3, N'Tôi Thấy Hoa Vàng Trên Cỏ Xanh', 8, 3, 1, 5, 100000, 125000, N'/images/products/p003.jpg', N'Câu chuyện về tuổi thơ của hai anh em Thiều và Tường ở một làng quê nghèo miền Trung, với những trò nghịch ngợm, mối tình đầu trong trẻo và cả những ghen tuông, hối hận rất trẻ con. Giọng văn hồn hậu đưa người đọc trở về những ngày thơ ấu bình yên.', 1, 0, 1, '2025-12-04T17:12:00'),
    (4, N'Người Đàn Ông Mang Tên Ove', 8, 4, 1, 5, 115200, 160000, N'/images/products/p004.jpg', N'Ove là một ông già cộc cằn, khó tính, sống theo những nguyên tắc cứng nhắc và luôn càu nhàu với hàng xóm. Cuộc sống của ông bị đảo lộn khi một gia đình trẻ ồn ào chuyển đến bên cạnh. Câu chuyện vừa hài hước vừa cảm động về tình người và sự tử tế.', 1, 1, 1, '2026-09-09T13:55:00'),
    (5, N'Cây Cam Ngọt Của Tôi', 8, 5, 4, 1, 81000, 108000, N'/images/products/p005.jpg', N'Zezé là cậu bé năm tuổi tinh nghịch sống trong một gia đình nghèo ở Brazil, người bạn thân nhất của cậu là cây cam ngọt nhỏ bé sau nhà. Qua đôi mắt trẻ thơ, cuốn sách kể về nỗi buồn, sự cô đơn và tình yêu thương làm nên con người.', 0, 0, 1, '2026-07-22T19:00:00'),
    (6, N'Hai Số Phận', 8, 6, 3, 8, 122500, 175000, N'/images/products/p006.jpg', N'Hai đứa trẻ sinh cùng ngày ở hai đầu thế giới: một người là con nhà giàu có ở Boston, một người là đứa trẻ mồ côi ở Ba Lan. Số phận đưa họ trở thành đối thủ không đội trời chung trong suốt cuộc đời. Một thiên tiểu thuyết đồ sộ về tham vọng, lòng kiêu hãnh và sự tha thứ.', 0, 0, 1, '2025-09-28T22:47:00'),
    (7, N'Mắt Biếc', 8, 3, 1, 5, 88000, 110000, N'/images/products/p007.jpg', N'Ngạn yêu Hà Lan, cô bạn có đôi mắt biếc từ thuở nhỏ ở làng Đo Đo. Thế nhưng khi lớn lên và rời làng ra phố, tình yêu ấy chỉ còn là nỗi nhớ day dứt không nguôi. Một trong những tác phẩm buồn và đẹp nhất của Nguyễn Nhật Ánh.', 0, 0, 1, '2026-03-16T21:09:00'),
    (8, N'Cà Phê Cùng Tony', 9, 7, 1, 5, 72000, 90000, N'/images/products/p008.jpg', N'Tập hợp những bài viết ngắn, dí dỏm nhưng thấm thía về cách sống, cách làm việc và cách đối nhân xử thế dành cho người trẻ. Mỗi câu chuyện như một tách cà phê buổi sáng giúp bạn thêm năng lượng để bắt đầu ngày mới.', 0, 0, 1, '2025-10-20T06:14:00'),
    (9, N'Trên Đường Băng', 9, 7, 1, 5, 76000, 95000, N'/images/products/p009.jpg', N'Cuốn sách dành cho những người trẻ đang chuẩn bị "cất cánh" vào đời: chuyện du học, khởi nghiệp, rèn luyện bản thân và giữ gìn sức khỏe. Lời khuyên được kể bằng giọng văn hài hước, gần gũi và đầy năng lượng tích cực.', 0, 0, 1, '2026-09-23T15:42:00'),
    (10, N'Thương Nhớ Mười Hai', 9, 8, 3, 1, 89200, 105000, N'/images/products/p010.jpg', N'Tùy bút kể về mười hai tháng trong năm của đất Bắc qua nỗi nhớ của người con xa quê. Mỗi tháng là một bức tranh về thời tiết, món ăn, phong tục và tình cảm gia đình, được viết bằng ngòi bút tinh tế, đầy thương cảm.', 0, 0, 1, '2026-06-30T12:15:00'),
    (11, N'Hà Nội Băm Sáu Phố Phường', 9, 9, 3, 4, 57800, 68000, N'/images/products/p011.jpg', N'Những trang tùy bút nhẹ nhàng ghi lại vẻ đẹp của Hà Nội xưa qua các món quà, các con phố và nếp sinh hoạt của người dân. Một cuốn sách nhỏ dành cho những ai yêu nét thanh lịch của đất kinh kỳ.', 0, 0, 1, '2025-09-12T21:37:00'),
    (12, N'Bến Xe', 10, 10, 3, 4, 54700, 76000, N'/images/products/p012.jpg', N'Câu chuyện tình yêu nhẹ nhàng mà day dứt giữa một cô gái bình thường và chàng trai lặng lẽ yêu cô suốt nhiều năm. Cuốn sách là lời nhắc nhở hãy trân trọng những người luôn chờ đợi mình ở bến xe của cuộc đời.', 0, 0, 1, '2026-07-26T20:03:00'),
    (13, N'Bên Nhau Trọn Đời', 10, 11, 3, 7, 101200, 135000, N'/images/products/p013.jpg', N'Sau bảy năm xa cách, Triệu Mặc Sênh trở về và tình cờ gặp lại Hà Dĩ Thâm, mối tình đầu năm nào. Những hiểu lầm dần được hóa giải trong câu chuyện tình yêu ngọt ngào, chung thủy đã làm say lòng nhiều thế hệ độc giả.', 0, 1, 1, '2026-07-13T19:28:00'),
    (14, N'Yêu Em Từ Cái Nhìn Đầu Tiên', 10, 11, 3, 7, 108800, 145000, N'/images/products/p014.jpg', N'Cô nàng Bối Vi Vi - hoa khôi khoa máy tính và cũng là cao thủ trong một trò chơi trực tuyến - bất ngờ được "kết hôn" trong game với một đại thần nổi tiếng. Chuyện tình từ thế giới ảo bước ra đời thực đầy dễ thương và hài hước.', 0, 0, 1, '2025-12-17T00:06:00'),
    (15, N'Anh Có Thích Nước Mỹ Không?', 10, 12, 3, 7, 91000, 130000, N'/images/products/p015.jpg', N'Những năm tháng đại học tươi đẹp của Trịnh Vy cùng nhóm bạn thân, với tình yêu đầu đời dành cho chàng trai đã bỏ đi du học. Cuốn sách là lời tạm biệt dịu dàng với tuổi trẻ và những giấc mơ dang dở.', 0, 0, 1, '2025-11-26T17:28:00'),
    (16, N'Phía Sau Nghi Can X', 11, 13, 3, 1, 82500, 110000, N'/images/products/p016.jpg', N'Một thầy giáo dạy toán thiên tài lặng lẽ giúp người phụ nữ hàng xóm che giấu vụ án mạng bằng một kế hoạch hoàn hảo đến đáng sợ. Cuộc đấu trí căng thẳng giữa hai bộ óc xuất chúng khiến người đọc nín thở đến trang cuối cùng.', 1, 0, 1, '2025-11-21T01:11:00'),
    (17, N'Mật Mã Da Vinci', 11, 14, 3, 7, 126000, 168000, N'/images/products/p017.jpg', N'Giáo sư Robert Langdon bị cuốn vào cuộc truy tìm bí mật tôn giáo ẩn giấu trong các tác phẩm của Leonardo da Vinci sau cái chết bí ẩn của người quản lý bảo tàng Louvre. Một cuốn tiểu thuyết ly kỳ với nhịp truyện dồn dập.', 0, 1, 1, '2025-09-15T16:04:00'),
    (18, N'Sherlock Holmes Toàn Tập - Tập 1', 11, 15, 3, 4, 152000, 190000, N'/images/products/p018.jpg', N'Tập đầu tiên trong bộ truyện kinh điển về thám tử lừng danh Sherlock Holmes và người bạn đồng hành, bác sĩ Watson. Những vụ án hóc búa được phá giải bằng óc quan sát và suy luận sắc bén đến kinh ngạc.', 0, 0, 1, '2026-09-26T04:30:00'),
    (19, N'Án Mạng Trên Chuyến Tàu Tốc Hành Phương Đông', 11, 16, 1, 5, 92000, 115000, N'/images/products/p019.jpg', N'Một hành khách bị sát hại trên chuyến tàu đang mắc kẹt giữa bão tuyết, và mỗi người trên tàu đều có thể là hung thủ. Thám tử Hercule Poirot phải dùng đến "những tế bào xám nhỏ bé" để tìm ra sự thật.', 0, 0, 1, '2025-10-25T18:17:00'),
    (20, N'Điều Kỳ Diệu Của Tiệm Tạp Hóa Namiya', 11, 13, 4, 1, 86200, 115000, N'/images/products/p020.jpg', N'Ba tên trộm trẻ trốn vào một tiệm tạp hóa bỏ hoang và nhận được những lá thư xin lời khuyên gửi đến từ quá khứ. Những câu chuyện tưởng như rời rạc dần đan vào nhau, ấm áp và đầy bất ngờ.', 0, 1, 1, '2026-05-05T15:35:00'),
    (21, N'Từ Tốt Đến Vĩ Đại', 12, 17, 1, 5, 138800, 185000, N'/images/products/p021.jpg', N'Vì sao một số công ty có thể bứt phá từ tốt trở thành vĩ đại, trong khi nhiều công ty khác thì không? Dựa trên nghiên cứu kéo dài nhiều năm, tác giả chỉ ra những nguyên tắc cốt lõi về lãnh đạo, con người và kỷ luật trong kinh doanh.', 1, 0, 1, '2025-10-14T16:16:00'),
    (22, N'7 Thói Quen Hiệu Quả', 12, 18, 5, 2, 131000, 168000, N'/images/products/p022.jpg', N'Cuốn sách trình bày bảy thói quen giúp mỗi người làm chủ bản thân, hợp tác hiệu quả với người khác và không ngừng hoàn thiện. Một tác phẩm kinh điển về phát triển cá nhân và nghệ thuật lãnh đạo.', 0, 0, 1, '2026-02-02T02:42:00'),
    (23, N'Khởi Nghiệp Tinh Gọn', 12, 19, 6, 3, 127200, 159000, N'/images/products/p023.jpg', N'Phương pháp xây dựng doanh nghiệp khởi nghiệp bằng cách thử nghiệm nhanh, đo lường và học hỏi liên tục từ khách hàng. Cuốn sách giúp các nhà sáng lập giảm thiểu rủi ro và tìm ra mô hình kinh doanh phù hợp.', 0, 0, 1, '2026-08-26T04:19:00'),
    (24, N'Lãnh Đạo Không Chức Danh', 12, 20, 1, 5, 78400, 98000, N'/images/products/p024.jpg', N'Ai cũng có thể trở thành người lãnh đạo dù không giữ bất kỳ chức vụ nào. Qua câu chuyện của một nhân viên bán sách, tác giả chia sẻ những bài học về trách nhiệm, sự đổi mới và cách tạo ảnh hưởng tích cực.', 0, 0, 1, '2026-01-03T21:02:00'),
    (25, N'Tiếp Thị 4.0', 13, 21, 1, 5, 108000, 135000, N'/images/products/p025.jpg', N'Cha đẻ của marketing hiện đại phân tích sự dịch chuyển từ tiếp thị truyền thống sang tiếp thị số trong thời đại kết nối. Cuốn sách cung cấp các mô hình giúp doanh nghiệp thấu hiểu hành trình khách hàng mới.', 0, 0, 1, '2025-09-21T17:31:00'),
    (26, N'Chiến Lược Đại Dương Xanh', 13, 22, 7, 3, 149200, 199000, N'/images/products/p026.jpg', N'Thay vì cạnh tranh khốc liệt trong "đại dương đỏ", doanh nghiệp hãy tạo ra khoảng thị trường mới chưa có đối thủ. Cuốn sách đưa ra công cụ và ví dụ thực tế để kiến tạo đại dương xanh của riêng mình.', 0, 1, 1, '2026-01-31T15:18:00'),
    (27, N'Nghệ Thuật Bán Hàng Bậc Cao', 13, 23, 5, 2, 110400, 138000, N'/images/products/p027.jpg', N'Những kỹ năng bán hàng được đúc kết từ nhiều thập kỷ kinh nghiệm: thấu hiểu khách hàng, đặt câu hỏi đúng và chốt đơn bằng sự chân thành. Cuốn cẩm nang dành cho bất kỳ ai làm nghề kinh doanh.', 0, 0, 1, '2026-09-30T18:02:00'),
    (28, N'Marketing Căn Bản', 13, 21, 7, 11, 142800, 168000, N'/images/products/p028.jpg', N'Giáo trình nhập môn trình bày các khái niệm nền tảng của marketing: nghiên cứu thị trường, hành vi người tiêu dùng, sản phẩm, giá, phân phối và truyền thông. Phù hợp cho sinh viên và người mới bắt đầu.', 0, 0, 1, '2026-01-29T16:44:00'),
    (29, N'Cha Giàu Cha Nghèo', 14, 24, 1, 5, 86200, 115000, N'/images/products/p029.jpg', N'Tác giả so sánh quan điểm về tiền bạc của hai người cha: một người học thức nhưng luôn khó khăn về tài chính, một người ít học nhưng trở nên giàu có. Cuốn sách giúp bạn thay đổi tư duy để tiền làm việc cho mình.', 1, 0, 1, '2026-02-05T17:56:00'),
    (30, N'Nhà Đầu Tư Thông Minh', 14, 25, 6, 3, 216800, 289000, N'/images/products/p030.jpg', N'Tác phẩm kinh điển về đầu tư giá trị, trình bày triết lý đầu tư an toàn, biên an toàn và cách kiểm soát cảm xúc trước biến động thị trường. Cuốn sách gối đầu giường của nhiều nhà đầu tư thành công.', 0, 1, 1, '2026-03-06T05:48:00'),
    (31, N'Bí Mật Tư Duy Triệu Phú', 14, 26, 5, 2, 81000, 108000, N'/images/products/p031.jpg', N'Mỗi người đều có một "kế hoạch tài chính" vô hình được hình thành từ suy nghĩ và thói quen. Tác giả chỉ ra sự khác biệt trong tư duy của người giàu và người nghèo, kèm các bài tập để thay đổi bản thân.', 0, 0, 1, '2026-01-24T08:55:00'),
    (32, N'Tâm Lý Học Về Tiền', 14, 28, 8, 11, 132300, 189000, N'/images/products/p032.jpg', N'Thành công về tài chính phụ thuộc vào cách hành xử nhiều hơn là trình độ hiểu biết. Qua những câu chuyện ngắn, tác giả lý giải cách con người suy nghĩ về tiền bạc, rủi ro và hạnh phúc.', 0, 1, 1, '2025-11-17T15:01:00'),
    (33, N'Người Giàu Có Nhất Thành Babylon', 14, 27, 6, 3, 78400, 98000, N'/images/products/p033.jpg', N'Những bài học quản lý tài chính cá nhân được kể qua các câu chuyện ngụ ngôn về thành Babylon cổ đại: tiết kiệm một phần thu nhập, đầu tư khôn ngoan và tránh xa những lời hứa hẹn làm giàu nhanh.', 0, 0, 1, '2026-05-08T05:21:00'),
    (34, N'Đắc Nhân Tâm', 15, 29, 5, 2, 86400, 108000, N'/images/products/p034.jpg', N'Cuốn sách nổi tiếng nhất mọi thời đại về nghệ thuật giao tiếp và ứng xử. Những nguyên tắc giản dị như lắng nghe, khen ngợi chân thành và đặt mình vào vị trí người khác giúp bạn chinh phục lòng người.', 1, 0, 1, '2026-04-26T12:38:00'),
    (35, N'Tuổi Trẻ Đáng Giá Bao Nhiêu', 15, 30, 4, 1, 72000, 90000, N'/images/products/p035.jpg', N'Những chia sẻ chân thành về việc học, đọc sách, đi và trải nghiệm của tuổi trẻ. Tác giả khuyến khích người trẻ dám sống khác, dám thử thách bản thân để không phải hối tiếc về sau.', 0, 0, 1, '2026-04-03T14:24:00'),
    (36, N'Đời Ngắn Đừng Ngủ Dài', 15, 20, 1, 5, 68000, 85000, N'/images/products/p036.jpg', N'Tuyển tập những lời khuyên ngắn gọn về cách sống trọn vẹn: thức dậy sớm, theo đuổi đam mê, đối mặt với nỗi sợ và đối xử tử tế với mọi người. Mỗi chương chỉ vài trang nhưng giàu sức gợi.', 0, 0, 1, '2026-09-24T01:30:00'),
    (37, N'Nghệ Thuật Tinh Tế Của Việc "Đếch" Quan Tâm', 15, 31, 3, 7, 89200, 119000, N'/images/products/p037.jpg', N'Thay vì cố gắng tích cực mọi lúc, hãy học cách chọn lọc những điều thật sự đáng để quan tâm. Bằng giọng văn thẳng thắn và hài hước, tác giả giúp người đọc sống thật với giới hạn của mình.', 0, 1, 1, '2026-04-16T06:34:00'),
    (38, N'Muôn Kiếp Nhân Sinh', 15, 32, 5, 2, 134400, 168000, N'/images/products/p038.jpg', N'Câu chuyện về những kiếp sống luân hồi của một doanh nhân thành đạt, qua đó gửi gắm thông điệp về luật nhân quả và cách sống hướng thiện trong thời đại nhiều biến động.', 1, 0, 1, '2025-11-14T23:28:00'),
    (39, N'Đọc Vị Bất Kỳ Ai', 16, 33, 7, 11, 71200, 89000, N'/images/products/p039.jpg', N'Những kỹ thuật tâm lý giúp bạn nhận biết suy nghĩ thật của người đối diện thông qua lời nói, cử chỉ và nét mặt. Cuốn sách hữu ích trong giao tiếp, đàm phán và công việc hằng ngày.', 0, 0, 1, '2026-06-26T16:09:00'),
    (40, N'Tư Duy Nhanh Và Chậm', 16, 34, 6, 3, 179200, 239000, N'/images/products/p040.jpg', N'Nhà tâm lý học đoạt giải Nobel Kinh tế giải thích hai hệ thống tư duy chi phối mọi quyết định của con người: nhanh, trực giác và chậm, lý trí. Cuốn sách giúp bạn nhận ra những thiên kiến khiến mình sai lầm.', 1, 1, 1, '2026-09-04T05:36:00'),
    (41, N'Sức Mạnh Của Thói Quen', 16, 35, 7, 3, 127200, 159000, N'/images/products/p041.jpg', N'Vì sao chúng ta làm những điều mình làm? Cuốn sách lý giải cơ chế hình thành thói quen ở cá nhân, tổ chức và xã hội, đồng thời chỉ ra cách thay thế thói quen xấu bằng thói quen tốt.', 0, 0, 1, '2026-03-17T12:38:00'),
    (42, N'Hiểu Về Trái Tim', 16, 36, 5, 13, 110400, 138000, N'/images/products/p042.jpg', N'Cuốn sách giúp người đọc nhìn sâu vào những cảm xúc như giận dữ, cô đơn, ghen tuông hay sợ hãi để hiểu và chuyển hóa chúng. Một hành trình trở về với chính mình bằng sự bình an và tỉnh thức.', 0, 0, 1, '2025-12-23T17:40:00'),
    (43, N'Dám Bị Ghét', 16, 37, 7, 1, 73500, 98000, N'/images/products/p043.jpg', N'Qua cuộc đối thoại giữa một triết gia và một chàng trai trẻ, cuốn sách giới thiệu tâm lý học Adler: hạnh phúc là lựa chọn, và để tự do, ta cần can đảm chấp nhận việc không làm hài lòng tất cả mọi người.', 0, 1, 1, '2026-03-29T05:29:00'),
    (44, N'Quẳng Gánh Lo Đi Và Vui Sống', 17, 29, 5, 2, 78400, 98000, N'/images/products/p044.jpg', N'Những phương pháp thực tế để thoát khỏi lo âu, giữ tinh thần lạc quan và tận hưởng cuộc sống. Cuốn sách được minh họa bằng nhiều câu chuyện có thật, dễ đọc và dễ áp dụng.', 0, 0, 1, '2025-10-30T03:51:00'),
    (45, N'Hạt Giống Tâm Hồn - Tập 1', 17, 38, 5, 2, 57800, 68000, N'/images/products/p045.jpg', N'Tuyển tập những câu chuyện ngắn ý nghĩa về tình yêu thương, lòng biết ơn và nghị lực sống. Mỗi câu chuyện là một hạt giống nhỏ nuôi dưỡng tâm hồn người đọc.', 0, 0, 1, '2026-09-27T13:39:00'),
    (46, N'Không Diệt Không Sinh Đừng Sợ Hãi', 17, 39, 6, 11, 88000, 110000, N'/images/products/p046.jpg', N'Thiền sư chia sẻ góc nhìn về sự sống và cái chết, giúp người đọc vượt qua nỗi sợ hãi và sống sâu sắc trong từng khoảnh khắc hiện tại.', 0, 0, 1, '2025-11-09T01:17:00'),
    (47, N'Dế Mèn Phiêu Lưu Ký', 18, 40, 2, 6, 40500, 45000, N'/images/products/p047.jpg', N'Cuộc phiêu lưu của chú Dế Mèn từ một chàng dế kiêu căng trở thành người biết sống vì bạn bè và lẽ phải. Tác phẩm thiếu nhi kinh điển của văn học Việt Nam qua nhiều thế hệ.', 0, 0, 1, '2026-02-19T07:48:00'),
    (48, N'Hoàng Tử Bé', 18, 41, 4, 1, 60000, 75000, N'/images/products/p048.jpg', N'Một phi công gặp hoàng tử bé đến từ tiểu hành tinh B612 giữa sa mạc Sahara. Qua những cuộc trò chuyện ngây thơ mà sâu sắc, câu chuyện nhắc người lớn đừng quên đứa trẻ trong mình.', 1, 0, 1, '2025-10-14T15:01:00'),
    (49, N'Totto-chan Bên Cửa Sổ', 18, 42, 4, 1, 78400, 98000, N'/images/products/p049.jpg', N'Cô bé hiếu động Totto-chan bị đuổi khỏi trường cũ và được nhận vào ngôi trường Tomoe với những lớp học trong toa tàu. Câu chuyện về một nền giáo dục tôn trọng trẻ em và nuôi dưỡng sự tự tin.', 0, 0, 1, '2025-08-20T12:48:00'),
    (50, N'Kính Vạn Hoa - Tập 1', 18, 3, 2, 6, 59500, 70000, N'/images/products/p050.jpg', N'Những câu chuyện vui nhộn về nhóm bạn Quý ròm, Tiểu Long và nhỏ Hạnh cùng bao trò nghịch ngợm ở trường lớp. Bộ truyện gắn liền với tuổi học trò của nhiều thế hệ độc giả.', 0, 0, 1, '2026-07-06T12:27:00'),
    (51, N'Harry Potter Và Hòn Đá Phù Thủy', 18, 43, 1, 5, 140200, 165000, N'/images/products/p051.jpg', N'Vào sinh nhật lần thứ mười một, cậu bé mồ côi Harry Potter phát hiện mình là một phù thủy và được nhận vào trường Hogwarts. Cuộc phiêu lưu đầu tiên mở ra thế giới phép thuật kỳ diệu đã chinh phục độc giả toàn cầu.', 1, 0, 1, '2026-07-03T03:18:00'),
    (52, N'Doraemon - Tập 1', 19, 44, 2, 6, 25000, NULL, N'/images/products/p052.jpg', N'Chú mèo máy Doraemon đến từ thế kỷ 22 giúp đỡ cậu bé hậu đậu Nobita bằng những bảo bối thần kỳ trong túi thần kỳ. Bộ truyện tranh đã trở thành tuổi thơ của bao thế hệ.', 0, 0, 1, '2026-04-24T19:26:00'),
    (53, N'Thám Tử Lừng Danh Conan - Tập 100', 19, 45, 2, 6, 25000, NULL, N'/images/products/p053.jpg', N'Cột mốc tập 100 của bộ truyện trinh thám nổi tiếng về cậu thám tử học sinh bị teo nhỏ thành Conan. Những vụ án mới tiếp tục hé lộ dần bí ẩn về Tổ chức Áo Đen.', 0, 0, 1, '2026-02-26T23:49:00'),
    (54, N'One Piece - Tập 100', 19, 46, 2, 6, 25000, NULL, N'/images/products/p054.jpg', N'Luffy và băng hải tặc Mũ Rơm bước vào trận chiến quyết định tại đảo Quỷ. Tập truyện đánh dấu chặng đường 100 tập của bộ manga phiêu lưu nổi tiếng.', 1, 0, 1, '2026-10-02T18:29:00'),
    (55, N'Dragon Ball - Tập 1', 19, 47, 2, 6, 25000, NULL, N'/images/products/p055.jpg', N'Cậu bé có đuôi Son Goku gặp cô gái Bulma và cùng nhau lên đường tìm kiếm bảy viên ngọc rồng. Khởi đầu của một trong những bộ truyện tranh hành động có ảnh hưởng lớn nhất.', 0, 0, 1, '2026-01-15T03:40:00'),
    (56, N'Shin - Cậu Bé Bút Chì - Tập 1', 19, 48, 2, 6, 20000, NULL, N'/images/products/p056.jpg', N'Cậu bé năm tuổi Shinnosuke lém lỉnh luôn khiến bố mẹ và mọi người xung quanh dở khóc dở cười. Những mẩu truyện ngắn hài hước dành cho cả trẻ em lẫn người lớn.', 0, 0, 1, '2026-01-27T05:27:00'),
    (57, N'10 Vạn Câu Hỏi Vì Sao - Khám Phá Vũ Trụ', 20, 38, 8, 4, 68000, 85000, N'/images/products/p057.jpg', N'Giải đáp những thắc mắc thú vị của trẻ về Mặt Trời, các hành tinh, sao chổi và hố đen bằng ngôn ngữ dễ hiểu cùng hình minh họa sinh động.', 0, 0, 1, '2026-07-25T02:46:00'),
    (58, N'Bách Khoa Tri Thức Cho Trẻ Em', 20, 38, 8, 4, 149200, 199000, N'/images/products/p058.jpg', N'Cuốn bách khoa toàn thư với hàng trăm chủ đề về thiên nhiên, động vật, cơ thể người, khoa học và lịch sử. Hình ảnh màu sắc giúp các em vừa học vừa chơi.', 0, 0, 1, '2026-01-21T12:39:00'),
    (59, N'Atlas Thế Giới Cho Trẻ Em', 20, 38, 2, 6, 127500, 150000, N'/images/products/p059.jpg', N'Tập bản đồ minh họa đầy màu sắc đưa các em đi qua các châu lục, quốc gia, danh lam thắng cảnh và những loài động vật đặc trưng của từng vùng đất.', 0, 0, 1, '2025-12-06T03:59:00'),
    (60, N'Giải Thích Ngữ Pháp Tiếng Anh', 21, 49, 9, 12, 148000, 185000, N'/images/products/p060.jpg', N'Cuốn sách hệ thống toàn bộ ngữ pháp tiếng Anh từ cơ bản đến nâng cao, mỗi chủ điểm đều có phần giải thích rõ ràng và bài tập thực hành kèm đáp án. Phù hợp cho học sinh, sinh viên ôn thi.', 0, 0, 1, '2026-03-14T15:17:00'),
    (61, N'English Grammar In Use', 21, 50, 13, 14, 288000, 320000, N'/images/products/p061.jpg', N'Giáo trình ngữ pháp tiếng Anh tự học nổi tiếng với cách trình bày hai trang: bên trái giải thích, bên phải là bài tập. Thích hợp cho người học trình độ trung cấp.', 0, 0, 1, '2026-07-16T13:15:00'),
    (62, N'Cambridge IELTS 18 Academic', 21, 38, 13, 14, 225000, 250000, N'/images/products/p062.jpg', N'Bộ đề thi IELTS Academic với bốn bài thi đầy đủ các kỹ năng Nghe, Đọc, Viết, Nói, kèm đáp án và bài mẫu tham khảo.', 0, 0, 1, '2025-08-22T14:14:00'),
    (63, N'Minna No Nihongo Sơ Cấp 1 - Bản Tiếng Nhật', 22, 38, 1, 5, 127800, 142000, N'/images/products/p063.jpg', N'Giáo trình tiếng Nhật sơ cấp được sử dụng rộng rãi tại các trường và trung tâm, gồm 25 bài học với hội thoại, mẫu câu và bài luyện tập.', 0, 0, 1, '2026-10-01T14:43:00'),
    (64, N'Tự Học Tiếng Nhật Cho Người Mới Bắt Đầu', 22, 38, 10, 10, 87200, 109000, N'/images/products/p064.jpg', N'Lộ trình tự học tiếng Nhật từ bảng chữ cái Hiragana, Katakana đến các mẫu câu giao tiếp thông dụng, có mã QR để nghe phát âm chuẩn.', 0, 0, 1, '2026-07-22T00:54:00'),
    (65, N'Giáo Trình Hán Ngữ 1', 23, 51, 12, 10, 75600, 89000, N'/images/products/p065.jpg', N'Giáo trình tiếng Trung cơ bản gồm phiên âm, cách viết chữ Hán và các bài hội thoại theo chủ đề, phù hợp cho người mới bắt đầu.', 0, 0, 1, '2026-07-19T07:12:00'),
    (66, N'Tự Học Tiếng Trung Cho Người Mới Bắt Đầu', 23, 38, 10, 10, 79200, 99000, N'/images/products/p066.jpg', N'Sách hướng dẫn học tiếng Trung từ con số 0 với phần phát âm, từ vựng và mẫu câu giao tiếp hằng ngày, kèm file nghe.', 0, 0, 1, '2025-10-15T12:54:00'),
    (67, N'Việt Nam Sử Lược', 24, 52, 3, 4, 128000, 160000, N'/images/products/p067.jpg', N'Bộ sử viết bằng chữ quốc ngữ trình bày lịch sử Việt Nam từ thời thượng cổ đến thời Pháp thuộc một cách ngắn gọn, mạch lạc và dễ tiếp cận.', 0, 0, 1, '2026-04-22T14:07:00'),
    (68, N'Lịch Sử Việt Nam Bằng Tranh - Tập 1', 24, 53, 1, 5, 27000, 30000, N'/images/products/p068.jpg', N'Bộ truyện tranh lịch sử giúp bạn đọc nhỏ tuổi tìm hiểu các giai đoạn dựng nước và giữ nước của dân tộc qua những hình vẽ sinh động.', 0, 0, 1, '2026-04-03T03:44:00'),
    (69, N'Đại Việt Sử Ký Toàn Thư', 24, 54, 3, 13, 382500, 450000, N'/images/products/p069.jpg', N'Bộ quốc sử quan trọng ghi chép lịch sử Việt Nam từ thời Hồng Bàng đến đời Lê, là tư liệu quý giá cho những ai muốn tìm hiểu cội nguồn dân tộc.', 0, 0, 1, '2026-09-03T19:05:00'),
    (70, N'Sapiens: Lược Sử Loài Người', 25, 55, 11, 9, 224200, 299000, N'/images/products/p070.jpg', N'Hành trình của loài người từ những con vượn sống trên cây đến chủ nhân của Trái Đất, qua ba cuộc cách mạng lớn: nhận thức, nông nghiệp và khoa học. Một cuốn sách khiến bạn nhìn lại lịch sử theo cách hoàn toàn mới.', 0, 0, 1, '2026-02-11T08:57:00'),
    (71, N'Súng, Vi Trùng Và Thép', 25, 56, 6, 9, 200000, 250000, N'/images/products/p071.jpg', N'Vì sao các nền văn minh phát triển không đồng đều? Tác giả lý giải vai trò của địa lý, nông nghiệp và dịch bệnh trong việc định hình số phận các dân tộc.', 1, 0, 1, '2026-08-30T23:53:00'),
    (72, N'Homo Deus: Lược Sử Tương Lai', 25, 55, 6, 9, 194200, 259000, N'/images/products/p072.jpg', N'Khi đã chiến thắng nạn đói, dịch bệnh và chiến tranh, loài người sẽ theo đuổi điều gì tiếp theo? Cuốn sách dự báo những thay đổi của nhân loại trong kỷ nguyên công nghệ sinh học và trí tuệ nhân tạo.', 0, 0, 1, '2026-09-22T21:40:00'),
    (73, N'Lược Sử Thời Gian', 26, 57, 1, 5, 92000, 115000, N'/images/products/p073.jpg', N'Nhà vật lý thiên tài giải thích những câu hỏi lớn về vũ trụ: vũ trụ bắt đầu như thế nào, thời gian là gì, hố đen ra sao, bằng ngôn ngữ dễ hiểu cho mọi độc giả.', 0, 1, 1, '2026-02-16T22:22:00'),
    (74, N'Vũ Trụ Trong Vỏ Hạt Dẻ', 26, 57, 1, 5, 140000, 175000, N'/images/products/p074.jpg', N'Phần tiếp nối của Lược Sử Thời Gian với nhiều hình minh họa màu, đưa người đọc đến những khám phá mới về lý thuyết dây, du hành thời gian và hình dạng của vũ trụ.', 1, 0, 1, '2026-02-05T05:17:00'),
    (75, N'Gen: Lịch Sử Và Tương Lai Của Nhân Loại', 26, 58, 8, 9, 280000, 350000, N'/images/products/p075.jpg', N'Câu chuyện về gen - đơn vị cơ bản của di truyền - từ những thí nghiệm của Mendel đến kỷ nguyên chỉnh sửa gen, đan xen với lịch sử gia đình đầy xúc động của chính tác giả.', 0, 0, 1, '2025-09-28T00:36:00'),
    (76, N'The Alchemist', 27, 1, 14, 14, 252000, 280000, N'/images/products/p076.jpg', N'The international bestseller about Santiago, an Andalusian shepherd boy who travels to Egypt in search of treasure and discovers the true meaning of following his dreams.', 0, 0, 1, '2026-03-13T07:13:00'),
    (77, N'Norwegian Wood', 27, 2, 15, 14, 288000, 320000, N'/images/products/p077.jpg', N'Toru Watanabe looks back on his student days in Tokyo, his devotion to the fragile Naoko and his friendship with the lively Midori, in a tender story of love and loss.', 0, 0, 1, '2026-04-19T22:42:00'),
    (78, N'It Ends With Us', 27, 59, 16, 14, 246500, 290000, N'/images/products/p078.jpg', N'Lily Bloom''s new life in Boston seems perfect when she falls for a charming neurosurgeon, until the past returns and forces her to make an impossible choice.', 0, 0, 1, '2026-02-09T22:23:00'),
    (79, N'The Midnight Library', 27, 60, 15, 14, 263500, 310000, N'/images/products/p079.jpg', N'Between life and death there is a library where Nora Seed can try out every life she might have lived, and discover what truly makes a life worth living.', 0, 0, 1, '2026-03-20T02:25:00'),
    (80, N'Atomic Habits', 28, 61, 15, 14, 306000, 340000, N'/images/products/p080.jpg', N'A practical guide to building good habits and breaking bad ones, showing how tiny changes compound into remarkable results over time.', 0, 0, 1, '2026-06-19T13:53:00'),
    (81, N'Rich Dad Poor Dad', 28, 24, 18, 14, 234000, 260000, N'/images/products/p081.jpg', N'Robert Kiyosaki contrasts the money lessons of his two fathers and explains why financial literacy, not income, is the key to building wealth.', 1, 0, 1, '2026-10-06T16:38:00'),
    (82, N'Zero to One', 28, 62, 15, 14, 297000, 330000, N'/images/products/p082.jpg', N'Notes on startups, or how to build the future: real progress comes from creating new things rather than copying what already works.', 0, 0, 1, '2026-02-05T14:52:00'),
    (83, N'The Psychology of Money', 28, 28, 19, 14, 270000, 300000, N'/images/products/p083.jpg', N'Short stories exploring the strange ways people think about money, and how to make better sense of one of life''s most important topics.', 0, 0, 1, '2026-02-26T20:45:00'),
    (84, N'The Very Hungry Caterpillar', 29, 63, 15, 14, 198000, 220000, N'/images/products/p084.jpg', N'The classic picture book following a tiny caterpillar as it eats its way through a week of food before turning into a beautiful butterfly.', 0, 0, 1, '2025-10-07T01:11:00'),
    (85, N'Harry Potter and the Philosopher''s Stone', 29, 43, 17, 14, 252000, 280000, N'/images/products/p085.jpg', N'Harry Potter has never even heard of Hogwarts when the letters start dropping on the doormat - the first book in the much-loved series.', 0, 0, 1, '2025-12-08T08:18:00'),
    (86, N'Diary of a Wimpy Kid', 29, 64, 15, 14, 212500, 250000, N'/images/products/p086.jpg', N'Greg Heffley tells the story of his first year of middle school in this hilarious illustrated journal that has made millions of children laugh.', 1, 0, 1, '2026-02-20T00:10:00'),
    (87, N'Charlie and the Chocolate Factory', 29, 65, 15, 14, 189000, 210000, N'/images/products/p087.jpg', N'Charlie Bucket finds the last golden ticket and wins a tour of Willy Wonka''s extraordinary chocolate factory, full of wonders and surprises.', 0, 0, 1, '2026-08-31T08:43:00');
