/* =============================================================
   BOOKLAND - DỮ LIỆU MẪU (chạy sau 01_CreateDatabase.sql)
   29 danh mục, 87 sản phẩm, 10 khách hàng, 30 đơn hàng
   Tài khoản demo:
     - Khách hàng: an.nguyen@example.com (hoặc 0900000001) / 123456
     - Quản trị  : admin / Admin@123   |   nhanvien01 / Nhanvien@123
   ============================================================= */
USE BookLandDB;
GO
SET NOCOUNT ON;
GO

-- Hình thức bìa
SET IDENTITY_INSERT CoverType ON;
SET IDENTITY_INSERT CoverType OFF;
GO

-- Danh mục (cha trước, con sau)
SET IDENTITY_INSERT Category ON;
SET IDENTITY_INSERT Category OFF;
GO

-- Tác giả
SET IDENTITY_INSERT Author ON;
SET IDENTITY_INSERT Author OFF;
GO

-- Nhà xuất bản
SET IDENTITY_INSERT Publisher ON;
SET IDENTITY_INSERT Publisher OFF;
GO

-- Nhà cung cấp
SET IDENTITY_INSERT Supplier ON;
SET IDENTITY_INSERT Supplier OFF;
GO

-- Sản phẩm
SET IDENTITY_INSERT Product ON;
SET IDENTITY_INSERT Product OFF;
GO

-- Chi tiết sản phẩm (thông số + tồn kho)
SET IDENTITY_INSERT ProductDetail ON;
SET IDENTITY_INSERT ProductDetail OFF;
GO

-- Ảnh phụ của sản phẩm (mặt sau + trang mẫu)
SET IDENTITY_INSERT ProductImage ON;
SET IDENTITY_INSERT ProductImage OFF;
GO

-- Khách hàng (mật khẩu demo: 123456, lưu dạng băm PBKDF2)
SET IDENTITY_INSERT Customer ON;
SET IDENTITY_INSERT Customer OFF;
GO

-- Người quản trị
SET IDENTITY_INSERT AdminUser ON;
SET IDENTITY_INSERT AdminUser OFF;
GO

-- Đơn hàng
SET IDENTITY_INSERT Orders ON;
SET IDENTITY_INSERT Orders OFF;
GO

-- Chi tiết đơn hàng
SET IDENTITY_INSERT OrderDetail ON;
SET IDENTITY_INSERT OrderDetail OFF;
GO

PRINT N'Đã nạp xong dữ liệu mẫu.';
SELECT (SELECT COUNT(*) FROM Category) AS Categories, (SELECT COUNT(*) FROM Product) AS Products,
       (SELECT COUNT(*) FROM Customer) AS Customers, (SELECT COUNT(*) FROM Orders) AS Orders,
       (SELECT COUNT(*) FROM OrderDetail) AS OrderDetails;
GO
